HOLDS = {'vanini2024','liu2024','goldak1984','debroy2018','king2014','bertoli2017','coen2022','solidpath2024','jmapro2024','feedforward2025'}
RETRIEVED = json.loads((ROOT / 'retrieval-records.json').read_text(encoding='utf-8'))
