ALIASES = {'yang2024':'sigler2024', 'soares2026':'reliability2026', 'hong2026':'fittingfree2026'}
records = []
abstracts = []
for key in ORIGINAL_KEYS + list(NEW_DOIS):
    support, limits, use, scope = DATA[key]
    rec = {'key': key, 'status': 'hold_metadata_only' if key in HOLDS else 'usable_with_scope', 'support':support, 'limits_counterevidence':limits, 'point_of_use':use, 'read_scope':scope}
    rec['identity_sources'] = ['../../literature/bibliography.bib'] if key in ORIGINAL_KEYS else [f'metadata/{key}-crossref.json',f'metadata/{key}-openalex.json']
    if key in NEW_DOIS: rec['doi'] = NEW_DOIS[key]
    if key in {'vanini2024','liu2024','ross2022'}: rec['identity_sources'] += [f'metadata/{key}-crossref.json',f'metadata/{key}-openalex.json']
    pdfkey = ALIASES.get(key,key)
    if (ROOT/'pdfs'/f'{pdfkey}.pdf').exists():
        rec['local_fulltext'] = f'pdfs/{pdfkey}.pdf'
        rec['local_extraction'] = f'text/{pdfkey}.txt'
    if pdfkey in RETRIEVED_BY_KEY: rec['retrieval'] = RETRIEVED_BY_KEY[pdfkey]
    if key in ORIGINAL_KEYS: rec['prior_read_evidence'] = '../../literature/exemplar-notes.md'
    records.append(rec)
    if key not in HOLDS:
        for provider in ['crossref','openalex']:
            p=ROOT/'metadata'/f'{key}-{provider}.json'
            if not p.exists():continue
            raw=json.loads(p.read_text(encoding='utf-8'))['response'];raw=raw.get('message',raw)
            a=raw.get('abstract')
            inv=raw.get('abstract_inverted_index')
            if inv:
                z={i:w for w,indices in inv.items() for i in indices}
                a=' '.join(z[i] for i in sorted(z))
            if a:
                a=html.unescape(re.sub('<[^>]+>','',a))
                # Crossref's Cunningham précis is editorial, not the scholarly abstract.
                if key=='cunningham2019' and provider=='crossref':continue
                abstracts.append(f'## {key} — {provider}\n\nSource: [{p.name}](metadata/{p.name}). DOI: https://doi.org/{rec.get("doi","")}\n\n{a}\n')
                break
(ROOT/'source-ledger.json').write_text(json.dumps({'date':'2026-10-01','scope':'This worker literature return; primary evidence and manuscript are unchanged. Usable means only the recorded claim/read scope, not fulltext or validation completeness.','counts':{'identities':len(records),'usable_with_scope':sum(x['status']=='usable_with_scope' for x in records),'hold_metadata_only':len(HOLDS)},'sources':records},ensure_ascii=False,indent=2),encoding='utf-8')
